package com.aegis.account;
import org.junit.jupiter.api.Test; import org.springframework.web.server.ResponseStatusException; import java.math.BigDecimal; import java.util.Optional; import java.util.UUID;
import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class AccountDebitServiceTest {
 @Test void referenceRetryReturnsPriorDebitWithoutChangingBalanceAgain(){var accounts=mock(AccountRepository.class);var ledger=mock(DebitRepository.class);UUID id=UUID.randomUUID();String reference="transfer-1";var prior=new DebitRecord(reference,id,new BigDecimal("3.2500"),"USD");when(ledger.findByReference(reference)).thenReturn(Optional.of(prior));var service=new AccountDebitService(accounts,ledger);assertEquals(reference,service.debit(id,reference,new BigDecimal("3.2500"),"USD").reference());verifyNoInteractions(accounts);verify(ledger,never()).save(any());}
 @Test void referenceCannotBeReusedForDifferentAmount(){var accounts=mock(AccountRepository.class);var ledger=mock(DebitRepository.class);UUID id=UUID.randomUUID();when(ledger.findByReference("transfer-1")).thenReturn(Optional.of(new DebitRecord("transfer-1",id,new BigDecimal("3.2500"),"USD")));var service=new AccountDebitService(accounts,ledger);var error=assertThrows(ResponseStatusException.class,()->service.debit(id,"transfer-1",new BigDecimal("4.0000"),"USD"));assertEquals(409,error.getStatusCode().value());verifyNoInteractions(accounts);}
}
